WITH metrics_long AS (SELECT * FROM (SELECT id, status, discount, amount, shipping_fee FROM orders) src UNPIVOT INCLUDE NULLS (metric_value FOR measure IN (discount AS DISCOUNT, amount AS AMOUNT_VAL, shipping_fee AS SHIPPING_FEE))) SELECT CASE WHEN metric_value >= 85 THEN 'HIGH' ELSE 'LOW' END AS metric_value_tier, COUNT(*) AS row_count, COUNT(*) FILTER (WHERE status = 'SHIPPED') AS shipped_rows, ROUND(AVG(metric_value), 2) AS avg_metric_value, SIZE(COLLECT_SET(status)) AS num_status, COUNT(DISTINCT id) AS distinct_ids FROM metrics_long GROUP BY metric_value_tier HAVING SIZE(COLLECT_SET(status)) < 1;
